import Model from 'flarum/common/Model';
export default class OAuthClient extends Model {
  name = (() => Model.attribute('name'))();
  redirectUris = (() => Model.attribute('redirectUris'))();
  scopes = (() => Model.attribute('scopes'))();
  confidential = (() => Model.attribute('confidential'))();
  revoked = (() => Model.attribute('revoked'))();
  source = (() => Model.attribute('source'))();
  plainSecret = (() => Model.attribute('plainSecret'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  updatedAt = (() => Model.attribute('updatedAt', Model.transformDate))();
}
flarum.reg.add('flarum-oauth-provider', 'admin/models/OAuthClient', OAuthClient);